-- profile: dms
-- Generated by DMS, never stowed; each is optional until DMS has run once.
for _, mod in ipairs({ "dms.layout", "dms.input", "dms.windowrules" }) do
    package.loaded[mod] = nil
    local ok, err = pcall(require, mod)
    if not ok then
        print("active_profile: " .. tostring(err))
    end
end
